import{_ as e,c as p,o as r,ah as s}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"22、【贲】 离下艮上","description":"周易尚氏学 - 22、【贲】 离下艮上","frontmatter":{"title":"22、【贲】 离下艮上","description":"周易尚氏学 - 22、【贲】 离下艮上"},"headers":[],"relativePath":"zh/classics/shangshi/027.md","filePath":"zh/classics/shangshi/027.md"}'),i={name:"zh/classics/shangshi/027.md"};function t(h,a,n,l,c,o){return r(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="_22、【贲】-离下艮上" tabindex="-1">22、【贲】 离下艮上 <a class="header-anchor" href="#_22、【贲】-离下艮上" aria-label="Permalink to “22、【贲】 离下艮上”">​</a></h1><p>归藏作荧惑。荧惑火星。史记察刚气以处荧惑。曰南方火。主夏日。丙丁是也。卦上艮为星。离亦为星。下离为火。艮亦为火。离主夏位南。艮纳丙亦南。故曰荧惑。于象恰合。至周易作贲。贲。释文云。傅氏作斑。文章貌。郑云文饰貌。太玄拟作饰。按卦一阴一阳相杂。相杂则有文。故曰斑。曰文饰。又按尔雅。龟三足曰贲。卦离艮皆为龟。而震为足。数三。正龟三足也。初二曰其趾其须。九三云儒如。六四云皤如。言其形也。上九云白贲。言其色也。杂卦云。责无色也。艮为黔。坎为隐伏。为黑。亦无色。无色即不明。不明故象言无敢折狱。盖山下有火。与地下有火略同。地下有火明夷。山下有火等耳。故孔子筮得贲不乐。以与明夷同也。后人谓山下有火。明不及远。皆读下为旁。故其义永不能通。前一义旧解皆从之。后一义鲜有述之者。故引信其义。以俟深于易理者定夺焉。</p><p>亨谓二。离夏故亨。传所谓柔来文刚也。小谓五。分泰二居上。五得中承阳。故曰小利有攸往。言利往五也。唐郭京举正。谓小为不。非。</p><p>彖曰。贵亨。柔来而文刚。故亨。分刚上而文柔。故小利有攸往。天文也。文明以上。人文也。观乎天丈以察时变。观乎人文以化成天下。</p><p>卦刚柔相杂故曰文。离日坎月。民星震辰。天文。离礼震乐。人文。离夏震春坎冬。故曰以察时变。震为生。艮为成。为天。故曰化成天下。朱子云。先儒说。天文上当有刚柔交错四字。</p><p>象曰。山下有火。贲。君子以明庶政。无敢折狱。</p><p>山下非山旁。火在山下。与地下同。直明夷耳。后儒谓明不及远者误也。艮为君子。明庶政。象每以相反见义。如同人曰类旅辨物。无妄曰时育万物。蛊曰振民育德皆是。兹因贲不明。君子反以明庶政。坎为狱。折狱须明。离在下不明。故无敢折狱。而无敢折狱。尤贲为无色无明之确征。</p><p>初九。贲其趾。舍车而徒。</p><p>初应在四。四震故曰趾。坎为车。初在车下。当然不乘而徒也。盖初九正当勿用之时。安于徒步。以遂其志者也。</p><h3 id="象曰。舍车而徒。义弗来也。" tabindex="-1">象曰。舍车而徒。义弗来也。 <a class="header-anchor" href="#象曰。舍车而徒。义弗来也。" aria-label="Permalink to “象曰。舍车而徒。义弗来也。”">​</a></h3><p>徒谓徒步。义弗乘者。言志行高洁。不肯苟乘也。</p><p>六二。贲其须。</p><p>艮为须。象失传。详焦氏易诂艮须在上。下离文之。故曰贲其须。其指上卦。言六二之须。谓上艮也。泰二往上成艮。故曰兴。二因得当位居中。故曰与上兴。候果谓三至上有颐象。二在颐下。故有须象。虽巧切。不知艮即为须也。</p><h3 id="象曰。贲其须。与上兴也。" tabindex="-1">象曰。贲其须。与上兴也。 <a class="header-anchor" href="#象曰。贲其须。与上兴也。" aria-label="Permalink to “象曰。贲其须。与上兴也。”">​</a></h3><p>兴起也。与上兴。即喜上兴也。</p><p>九三。贵如濡如。永占吉。</p><p>坎水故曰德如。阳贞于三当位。前临重阴。故曰永贞吉。</p><h3 id="象曰。永贞之吉。终莫之陵也。" tabindex="-1">象曰。永贞之吉。终莫之陵也。 <a class="header-anchor" href="#象曰。永贞之吉。终莫之陵也。" aria-label="Permalink to “象曰。永贞之吉。终莫之陵也。”">​</a></h3><p>之往也。三应在上。上艮为陵。乃上不应。故终莫之陵。永贞于三吉也。又前临重阴。皆顺三。无有陵越之患也。六四。贲如皤如。白马翰如。匪寇婚媾。左传宣二年。皤其腹。疏皤腹貌。卦三至上互大离。离为大腹。故曰皤如。释文皤苟作波。郑陆作幡（左虫）。音烦。按皤通番。番音烦。郑陆读烦声是也。凡易如此等辞。往往用韵。疑番与翰协。诗大雅申伯番番。徒御蝉蝉（左口）。戎有良翰。番与翰协。与此同也也。陆绩云。震为白。为马。按震为羽翰。翰象失传 详焦氏易诂翰如马行貌。言疾如羽翰也。四乘坎。坎为寇。疑其逼己。岂知四当位。下有正应。三无能害之。终得与初婚媾也。象曰。六四当位。疑也。匪寇婚媾。终无尤也。疑谓疑三。坎为疑。</p><p>六五。贲于丘园。束帛久久。吝。终吉。</p><p>艮为丘园。坤为帛。乾环约其两端。故曰束帛。子夏传。五匹为束。三玄二熏。象阴阳。戋戋。马训为委积。虞作多。易林旅之丰云。束帛戋戋。膊（左贝）我孟宣。似亦以盛多为训。俗解因戋通残。便训戋戋为薄物。又或作残落者非也。仪礼士冠上虞礼。周礼大宗伯注。皆以束帛为十端。每端丈八尺。两端合卷。决为五匹。皆与子夏传同。然则束帛五匹者。乃先王之定制。戈戈乃形容束帛之盛。谓薄物固非。残落尤谬也。下元应故吝。上承阳。故终吉。彖谓小利往。以此。</p><h3 id="象曰。六五之吉。有喜也。" tabindex="-1">象曰。六五之吉。有喜也。 <a class="header-anchor" href="#象曰。六五之吉。有喜也。" aria-label="Permalink to “象曰。六五之吉。有喜也。”">​</a></h3><p>五承阳。故有喜。</p><p>上九。白贲。无咎。</p><p>贲而曰白。其为物也明矣。若训为饰为文为斑为黄白色。范望太玄视首上九注为色不纯。高诱吕览贲字注此二字皆不能通。诸儒据绘事后素。曲为之说。无当也。盖艮为贲。责无色。故曰白贲。</p><h3 id="象曰。白贲无咎。上得志也。" tabindex="-1">象曰。白贲无咎。上得志也。 <a class="header-anchor" href="#象曰。白贲无咎。上得志也。" aria-label="Permalink to “象曰。白贲无咎。上得志也。”">​</a></h3><p>下乘重阴。故曰得志。言阳得阴而通也。大畜上九曰道大行也。损上九曰大得志。益九五曰大得志。颐上九曰大有庆。与此义皆同。乃二千年旧解。少能知其故者。真可谓也。</p>',27)])])}const m=e(i,[["render",t]]);export{_ as __pageData,m as default};
